def migrate_files_from_expenses_to_core(apps, schema_editor):

    LegacyFile = apps.get_model("expenses", "File")
    File = apps.get_model("core", "File")
    Claim = apps.get_model("core", "Claim")

    expense_claims = dict(
        Claim.objects.filter(expense_data__isnull=False).values_list(
            "expense_data_id", "id"
        )
    )
    invoice_claims = dict(
        Claim.objects.filter(invoice_data__isnull=False).values_list(
            "invoice_data_id", "id"
        )
    )

    File.objects.bulk_create(
        File(
            id=f.id,
            file=f.file,
            claim_id=(
                expense_claims[f.expense_id]
                if f.expense_id is not None
                else invoice_claims[f.invoice_id]
            ),
        )
        for f in LegacyFile.objects.exclude(expense_id=None, invoice_id=None)
    )


def migrate_comments_from_expenses_to_core(apps, schema_editor):

    LegacyComment = apps.get_model("expenses", "Comment")
    Comment = apps.get_model("core", "Comment")
    Claim = apps.get_model("core", "Claim")

    expense_claims = dict(
        Claim.objects.filter(expense_data__isnull=False).values_list(
            "expense_data_id", "id"
        )
    )
    invoice_claims = dict(
        Claim.objects.filter(invoice_data__isnull=False).values_list(
            "invoice_data_id", "id"
        )
    )

    legacy_comments = list(LegacyComment.objects.all())

    Comment.objects.bulk_create(
        Comment(
            id=c.id,
            author_id=c.author_id,
            content=c.content,
            claim_id=(
                expense_claims[c.expense_id]
                if c.expense_id is not None
                else invoice_claims[c.invoice_id]
            ),
        )
        for c in legacy_comments
    )

    for c in legacy_comments:
        Comment.objects.filter(id=c.id).update(date=c.date)


def reset_sequences(apps, schema_editor):
    # reset id increments
    models = [
        apps.get_model("core", "Profile"),
        apps.get_model("expenses", "ExpenseData"),
        apps.get_model("invoices", "InvoiceData"),
        apps.get_model("core", "File"),
        apps.get_model("core", "Comment"),
    ]
    for sql in schema_editor.connection.ops.sequence_reset_sql(no_style(), models):
        schema_editor.execute(sql)


